 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Edge rows contain one or more contiguous color sequences. Each isolated
    # marker is expanded into its corresponding sequence, aligned by color.
    motifs = []
    for edge_row in (grid[0], grid[-1]):
        run = []
        for value in edge_row:
            if value:
                run.append(value)
            elif run:
                motifs.append(run)
                run = []
        if run:
            motifs.append(run)
    for r in range(1, len(grid) - 1):
        cells = [(c, v) for c, v in enumerate(grid[r]) if v]
        if len(cells) != 1:
            continue
        c, v = cells[0]
        motif = next((m for m in motifs if v in m), None)
        if motif is None:
            continue
        start = c - motif.index(v)
        for j, color in enumerate(motif):
            x = start + j
            if 0 <= x < len(grid[r]):
                out[r][x] = color
    return out
